import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Cij = (k=1...m) AikBkj
        // Cnl = Anm x Bml

        // input n,m,l
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int l = scanner.nextInt();

        // create Anm
        int[][] Anm = new int[n][m];
        for(int i=0; i<n; i++){
            for(int j=0; j<m; j++){
                Anm[i][j] = scanner.nextInt();
            }
        }

        // create Bml
        int[][] Bml = new int[m][l];
        for(int i=0; i<m; i++){
            for(int j=0; j<l; j++){
                Bml[i][j] = scanner.nextInt();
            }
        }

        // create Cnl
        long[][] Cnl = new long[n][l];
        for(int iN=0; iN<n; iN++){
            for(int kM=0; kM<m; kM++){            
                for(int jL=0; jL<l; jL++){
                    Cnl[iN][jL] += Anm[iN][kM] * Bml[kM][jL];
                }
            }
        }

        // display
        printArray(Cnl);

    }

    public static void printArray(long[][] array) {
        int row = array.length;
        int width = array[0].length;
        for(int i=0; i<row; i++){
            for(int j=0; j<width; j++){
                System.out.print(array[i][j]);
                if (j != width-1) { System.out.print(" "); }
            }
            System.out.println();
        }
    }

}

/**
n×m  の行列 A  と m×l  の行列 B  を入力し、それらの積である n×l  の
 を出力するプログラムを作成してください。行列 C  の各要素 c ij   は次の式で得られます：

 １行目に n 、m 、l  が空白区切りで与えられます。

続く行に n×m  の行列 A  と m×l  の行列 B  が与えられます。

 */

//スキャナつかうため

import java.util.Scanner;

public class Main {
	// プログラムのエントリポイント
	public static void main(String[] args) {
		// 入力ストリームの生成
		Scanner sc = new Scanner(System.in);
		// 3つの数値を受け取る
		int intN = sc.nextInt();
		int intM = sc.nextInt();
		int intL = sc.nextInt();
		// 受け取った数値で配列をつくる
		// Aの行列
		int[][] gyoua = new int[intN][intM];
		// Bの行列
		int[][] gyoub = new int[intM][intL];
		// Cの行列
		long[][] gyouc = new long[intN][intL];
		// 数値をAの配列の数受け取る
		for (int i = 0; i < intN; i++) {
			for (int j = 0; j < intM; j++) {
				gyoua[i][j] = sc.nextInt();
			}
		}
		// Bの配列の数数値を受け取る
		for (int i = 0; i < intM; i++) {
			for (int j = 0; j < intL; j++) {
				gyoub[i][j] = sc.nextInt();
			}
		}
		// 計算
		for (int i = 0; i < intN; i++) {
			for (int j = 0; j < intL; j++) {

				for (int k = 0; k < intM; k++) {
					// Cの配列に計算結果を入れていく
					gyouc[i][j] += gyoua[i][k] * gyoub[k][j];
				}
				System.out.print(gyouc[i][j]);
				if (j != intL - 1) {
					// 空白
					System.out.print(" ");
				}
			}
			// 改行
			System.out.println();
		}

	}
}

import java.util.Scanner;
import java.util.function.Function;

public class Main {

    public static void main(String[] args) {
        new Main().solve();
    }

    Scanner sc = new Scanner(System.in);

    void solve() {
        int n, m, l;
        long[][] m1, m2, m3;
        n = sc.nextInt();
        m = sc.nextInt();
        l = sc.nextInt();
        m1 = new long[n][];
        for (int i = 0; i < n; ++i) {
            m1[i] = new long[m];
            for (int j = 0; j < m; ++j) {
                m1[i][j] = sc.nextInt();
            }
        }
        m2 = new long[m][];
        for (int i = 0; i < m; ++i) {
            m2[i] = new long[l];
            for (int j = 0; j < l; ++j) {
                m2[i][j] = sc.nextInt();
            }
        }
        m3 = new long[n][];
        for (int i = 0; i < n; ++i) {
            m3[i] = new long[l];
            for (int j = 0; j < l; ++j) {
                long temp = 0;
                for (int k = 0; k < m; ++k) {
                    temp += m1[i][k] * m2[k][j];
                }
                m3[i][j] = temp;
            }
        }

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < l - 1; ++j) {
                System.out.print(m3[i][j] + " ");
            }
            System.out.println(m3[i][l - 1]);
        }

    }

}

