class Main {

	public static void main(String[] args) {
		new Main().exec();
	}

	void exec() {
		Scanner sc = new Scanner(System.in);
		int a = sc.nextInt();
		int b = sc.nextInt();
		int k = sc.nextInt();
		for (int i = Math.min(a, b); i >= 1; --i) {
			if (a % i == 0 && b % i == 0) {
				--k;
				if (k == 0) {
					System.out.println(i);
					sc.close();
					return;
				}
			}
		}
		sc.close();
	}

}

